def main():
    requirements=json.loads((ROOT/'contracts/requirements.json').read_text('utf-8'))
    scenarios={t['id']:{**t,'milestone':r['milestone']} for r in requirements for t in r['tests']}
    rows=[]
    for suffix,(covered,nodes,paths,note) in M0.items():
        tid='M0-AT'+suffix
        rows.append({'test_id':tid,'scenario':scenarios[tid]['scenario'],'literal_scenario_covered':covered,
            'current_tree_pass_claimed':False,'test_nodeids':nodes,'evidence_paths':paths,
            'missing_evidence_paths':[p for p in paths if not (ROOT/p).is_file()],
            'observed_scope':note,'gap':None if covered else note,'generated_by':'/root/acceptance_harness'})
    assert len(rows)==36
    result={'scope':'Historical scoped observations; not current source-bound gate certificates','entries':rows}
    path=ROOT/'.agent/tmp/evidence/reviews/m0-acceptance-map.json';path.write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    operations=[]
    for tid,(covered,nodes,paths,note) in OPERATIONS.items():
        operations.append({'test_id':tid,'scenario':scenarios[tid]['scenario'],'literal_scenario_covered':covered,
            'current_tree_pass_claimed':False,'test_nodeids':nodes,'evidence_paths':paths,
            'missing_evidence_paths':[p for p in paths if not (ROOT/p).is_file()],
            'observed_scope':note,'gap':None if covered else note,'generated_by':'/root/acceptance_harness'})
    operation_path=ROOT/'.agent/tmp/evidence/reviews/operations-acceptance-map.json'
    operation_path.write_text(json.dumps({'scope':result['scope'],'entries':operations},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    sources=[path,operation_path,ROOT/'.agent/tmp/reports/core-evidence/ir-acceptance-map.json',ROOT/'.agent/tmp/frontend/evidence/acceptance-map.json',ROOT/'.agent/tmp/reports/core-evidence/root-acceptance-map.json',ROOT/'.agent/tmp/evidence/reviews/m2-compound-acceptance-map.json']
    joined={tid:{'test_id':tid,'scenario':s['scenario'],'milestone':s['milestone'],'observations':[]} for tid,s in scenarios.items()}
    for source in sources:
        if not source.exists():continue
        loaded=json.loads(source.read_text('utf-8'))
        for row in loaded.get('entries',[]):
            if row.get('test_id') in joined:
                joined[row['test_id']]['observations'].append({'mapping_file':source.relative_to(ROOT).as_posix(),**row})
    (ROOT/'.agent/tmp/evidence/observed-scenario-map.json').write_text(json.dumps({'scope':result['scope'],
        'warning':'A true literal_scenario_covered assertion is historical scoped evidence, never an automatic current gate pass.',
        'tests':list(joined.values())},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    lines=['# Formal gate evidence gaps','',
        'This report distinguishes scoped historical behavior coverage from current source-bound gate certificates. It does not declare a milestone complete.', '',
        'Every gate still requires current registered command evidence, applicable independent agent review, and the proof kinds in harness/gate-policy.json. Real Provider proof is unavailable until explicit authorization, fixed model configuration and budget are supplied. Both research-paper sources have independent exact corrected-source gold; this does not retroactively pass raw parser output or replace live translation review. The dedicated cross-page resource fixture has actual inference evidence with visible source-review blocking for an ambiguous graphic group; see the exact runtime and independent scope records.', '']
    prerequisites=json.loads((ROOT/'.agent/harness/gate-prerequisites.json').read_text('utf-8'))
    for gate in json.loads((ROOT/'contracts/exit-gates.json').read_text('utf-8')):
        members=[row for row in joined.values() if scenarios[row['test_id']]['requirement_id'] in gate['requirements'] or row['test_id'] in prerequisites.get(gate['id'],[])]
        partial=[row for row in members if not any(o.get('literal_scenario_covered') is True for o in row['observations'])]
        lines += [f"## {gate['id']} {gate['title']}", '', 'Required evidence: '+gate['evidence'], '',
            f"Historical literal observations: {len(members)-len(partial)}/{len(members)} scenarios. These are not current gate passes.", '']
        for row in partial:
            gaps=list(dict.fromkeys(str(o.get('gap') or o.get('observed_scope') or 'See the referenced scoped agent record.') for o in row['observations']))
            lines += [f"- **{row['test_id']}** {row['scenario']} " + ' | '.join(gaps)]
        if not partial:
            lines += ['No unmapped literal behavior gap remains in the supplied observations; a stable-source rerun and independent review registration are still required.']
        lines += ['']
    (ROOT/'.agent/tmp/evidence/formal-gate-gap-report.md').write_text('\n'.join(lines),encoding='utf-8')
    print(json.dumps({'tests':len(joined),'tests_with_observations':sum(bool(r['observations']) for r in joined.values()),
        'maps_loaded':[str(p.relative_to(ROOT)) for p in sources if p.exists()]}))


if __name__=='__main__':main()
